Proceso SumaDePares
    Definir cantidad Como Entero;
    Definir i Como Entero;
    Definir valor Como Entero;
    Definir suma Como Entero;
    Leer cantidad;
    suma <- 0;
    Para i <- 1 Hasta cantidad Hacer
        Leer valor;
        Si valor mod 2 = 0 Entonces
            suma <- suma + valor;
        FinSi
    FinPara
    Escribir suma;
FinProceso
